float ang1 = atan(uv1.y, uv1.x);
float rad2 = length(uv1);
float rad1 = -1*rad2 + 0.05/(rad2-0.08);
vec2 uv2 = vec2 (ang1/6.28, clamp(rad1,-8, 8.0 ));
uv2.y = uv2.y / 2.0 + uTime / 2.0;
vec3 tube = lum(texture(sampler_noise_hq, corr*uv2));
//tube  = sqrt(abs (tube-.8));
tube-=roam_sin.wzy*roam_cos;
vec2 uv3 = uv + tube / 64.0;
double3 blur = lum(GetBlur1 (uv3));
double3 crisp =(GetPixel(uv3));
double3 ret2 = crisp + blur;
double3 lblue = vec3 (0.3, 0.5, 1.0 ) / 3.0 *(1.0 - rad);
ret2 = ret2 + lblue;
ret = -1*tube*rad + (1.0 + q24 / 4.0)*ret2 * (1.0 - tube / 2.0);
}

